"""Render bounded V13 diagnostics. A requirements matrix is never serialized as a completed plan."""
from pathlib import Path
import json,gzip,hashlib,re
R=Path('docs/det-engine/v13');E=R/'evidence/final'
data=json.load(gzip.open(E/'study.json.gz','rt'));rep=json.loads((R/'evidence/reproducibility.json').read_text())
full=json.loads((R/'evidence/validation/commands.json').read_text());delta=json.loads((R/'evidence/final-delta/commands.json').read_text())
assert rep['identical'] and len(full)==4 and all(x['exitCode']==0 for x in full) and len(delta['proof'])==2 and all(x['exitCode']==0 for x in delta['proof'])
for x in rep['comparison']:assert hashlib.sha256((E/x['file']).read_bytes()).hexdigest()==x['first']==x['replay']
def table(h,rows):return '\n'.join(['| '+' | '.join(h)+' |','|'+'|'.join('---'for _ in h)+'|']+['| '+' | '.join(str(x).replace('|','/')for x in row)+' |'for row in rows])
def put(name,text): (R/name).write_text(text.rstrip()+'\n')
audit=data['catalogue']['audit'];byid={x['id']:x for x in audit}
text='# Intégrité du catalogue — V13\n\nPérimètre : offres natives des seize semaines pour les deux profils synthétiques, plus cinq témoins prioritaires. Ce n’est pas une revue exhaustive de toute la bibliothèque. Aucune fiche de production ni aucun validateur historique n’est modifié.\n\n'
text+=f'{len(audit)} sources uniques examinées. La couverture temporelle est distinguée de la pertinence sportive et de la faisabilité individuelle.\n\n'
text+=table(['Diagnostic de source','Nombre'],list(data['catalogue']['counts'].items()))
text+='\n\nLe premier essai réutilisait trop largement literalDose V10 : une sous-recette Main pouvait être prise pour toute la séance, et des blocs composés étaient omis. Ses six conflits initiaux ne sont pas six fiches prouvées impossibles. Les sorties sont conservées dans evidence/attempt-1 ; la couche V13 exige une grammaire couverte et sépare borne minimale, blocs quantifiés, totalité explicitement décrite et temps non attribué. La production reste intacte.\n\n'
ids=['C_BRICK_TRANSITION_DRILL','C_IM_AERO_HOLD','C_BIKE_AERO_POSITION_DRILLS','V3_BIKE_Z2_PROGRESSIF','V3_BIKE_Z2_ENDURANCE_LONG','D_TAPER_BIKE_OPENER','B_BIKE_SST_3x12_PRO','B_BIKE_VO2_6x3_PRO','B_RUN_TEMPO_2x20_PRO','B_BRICK_SEUIL_LONG_BUILD_IM']
text+=table(['Source','Annonce, min','Blocs quantifiés','Borne minimale certaine','Fourchette de recette complète connue','Diagnostic'],[[i,byid[i]['originalRange'],byid[i]['knownTimedBlocksRange'],byid[i]['knownMandatoryLowerMin'],byid[i]['fullRecipeTimeRange'],byid[i]['status']]for i in ids if i in byid])
text+='\n\n- Brick de transition :15 +5×(3+3)+10 =55 min actifs au minimum, avant transitions inconnues ; le maximum annoncé45 est dépassé.\n- Position :4×15 avec3–4 repos5 donne75–80 min de blocs ;6×10 avec5–6 repos5 donne85–90. Le minimum60 annoncé ne permet pas toute la recette. Main seul ne prouve toutefois pas que120 min soit impossible : le reste du temps n’est pas documenté, et aucun échauffement n’est inventé.\n- Vélo progressif : trois blocs30 min plus15+15 min donnent120 min pour la recette explicite, sans compression ni extension d’une variante en prose.\n- Longue V3 :20 min +150–270 min +10 min donne180–300 ;150 min n’exécute pas tous les éléments.\n- Opener vélo composé :30 +4×1 +(3–4)×3 +10 =53–56 min de blocs, pas13–16. Les valeurs annoncées sous53 ne couvrent pas les éléments obligatoires. Le rappel d’intensité de la source n’est pas interdit universellement en taper.\n- Les seules répétitions SST/VO2/tempo ne détaillent pas tout le temps annoncé : le supplément reste non attribué. Il n’est pas automatiquement classé comme contradiction, ni fabriqué en échauffement. Le brick long à plusieurs disciplines dépasse la grammaire du parseur partiel ; sa projection historique est conservée comme non probante.\n\n## Phases, intensités et contexte\n\nLes phases déclarées et phases effectives issues de la normalisation existante sont enregistrées pour chaque source, avec zones, prérequis et contexte particulier. L’overlay du brick garde les mêmes phases et intensités ; sa phase effectivepeak ne devient pasbuild pour le rendre sélectionnable. L’horizon natif de ces cas ne contient pas de phasepeak explicite : cela n’invalide pas toutes les préparations, mais cette fiche ne peut être imposée à un autre contexte sans revue.\n\nLes fenêtres littérales J−5 à J−3 sont vérifiées sur les dates existantes en plus du placement V11. Une date manquante ne confirme pas le placement. Les exclusions explicites de taper sont conservées sans transformer toute récupération en interdiction générale des rappels d’intensité. Le diagnostic temporel ne certifie ni charge interne ni pertinence physiologique.\n\nLa majeure partie des sources reste hors grammaire temporelle complète ; cela constitue une limite de couverture, pas une liste de séances invalides. Aucun résultat d’audit n’est promu automatiquement dans la doctrine.'
put('CATALOGUE_INTEGRITY.md',text)
text='# Nage complète en45 minutes : non confirmée\n\nLa source A_SWIM_AEROBIC_MULTI_NAGES contient200 m faciles,8×(100 m crawl+50 m dos+50 m brasse), puis200 m faciles, avec repos15 s. Total2000 m :800 m crawl,400 m dos,400 m brasse et400 m périphériques. Les repos entre huit séries représentent105 s ; l’inclusion du dernier repos donne120 s. Ils ne sont pas supprimés.\n\n'
text+=table(['Profil','CSS synthétique de crawl','Borne partielle conditionnelle crawl+repos','Séance complète45 min confirmée'],[[p['profile'],p['result']['swim']['cssSecPer100m'],round(p['result']['swim']['partialKnownLowerMinutes'],2)if p['result']['swim']['partialKnownLowerMinutes']is not None else'inconnue','non']for p in data['profiles']])
text+='\n\nLe calcul partiel du profil aérobie réutilise la grille de zones existante via deriveTrainingZones et le domaine de doctrine. C’est une conversion arithmétique sous convention TFCL et référence fictive, pas une borne physiologique validée. Les dates/méthodes du test CSS ne sont pas établies. Ce CSS de crawl ne devient pas une allure de dos ou brasse. Pour l’équilibré, le CSS est absent et n’est pas estimé à partir de VO2max, VLamax ou du niveau.\n\nLe temps des autres nages, des éléments périphériques et des transitions n’est pas connu. Une borne partielle inférieure à45 min ne prouve donc pas que tout rentre dans45 min. L’intervalle catalogue40–55 accepte numériquement45 ; ce contrôle est reproduit et conservé, avec la nouvelle limite individuelle explicitée. Aucune impossibilité physiologique générale n’est revendiquée.\n\nLa fiche A_SWIM_CONTINUOUS_2K comporte elle aussi des éléments hors bloc principal :400 m multi-nages +2000 m continus +200 m dos, soit2600 m de contenu. Le nom2K décrit le principal, pas la distance totale. Cela ne résout pas les temps individuels manquants.\n\nDécision : ne pas libérer la compensation55→45 min V12 sans preuve d’exécution complète au domaine voulu, repos conservés, données de nages et réponse utilisable. Besoin de preuves existantes/observables et de leur provenance ; pas de nouveau questionnaire de charge ni d’interface de production.'
put('SWIM_45_FEASIBILITY.md',text)
o=data['overlay']
text='# Overlay expérimental du brick de transition\n\nCorrection de contrat actif, pas fabrication d’une séance complète admissible. Source de production inchangée, même identifiant et empreinte conservés.\n\n'
text+=table(['Élément','Résultat'],[['Annonce originale',o['originalAdvertisedRange']],['Vélo actif connu',o['components']['bike']],['Course active connue',o['components']['run']],['Total actif connu',o['components']['knownActiveMinutes']],['Temps des transitions','inconnu'],['Durée totale maximale','inconnue'],['Séance complète exécutable',o['fullSessionExecutable']],['Erreur historique à55 min',o['originalCheck']['errors']],['Contrôle de la portion active corrigée',o['activePortionCheck']],['Phases/intensités modifiées','non']])
text+='\n\nLes15 min de vélo initiales, cinq séquences de3 min vélo/3 min course, puis10 min de jogging donnent30 min vélo et25 min course. Un objectif de transition sous30 s n’est ni une observation ni une durée nulle. Le contrat expérimental actif devient55 min ; le contrat de temps total reste minimum55, maximum inconnu. Il n’est pas inséré comme séance55 min dans un plan.\n\nLe contrôle original conserve catalogue_duration. Le contrôle parallèle de portion active n’est jamais présenté comme passage du validateur original ni comme validation du temps total. La couche ne supprime aucun bloc et ne fait pas passer55 min pour55 min de vélo. Aucun crédit de longue autonome n’est attribué.\n\nLe contexte source restepeak et les restrictions originales sont conservées. Les prérequis individuels, la durée totale et le placement doivent être établis avant toute utilisation. Tous les autres bricks ne sont pas déclarés incompatibles par ce témoin.'
put('BRICK_EXPERIMENTAL_OVERLAY.md',text)
text='# Faisabilité Ironman16 semaines — aucune préparation complète admissible\n\nLes deux horizons sont examinés jusqu’à S16, avant puis après réconciliation du paramètre expérimental de budget. Ce tableau décrit les exigences et leurs témoins ; **il n’est pas un calendrier de séances prescrit**. Aucun trou n’est rempli par un repos, une séance ou un événement fictif.\n\n'
for p in data['profiles']:
 f=p['result'];old=p['originalFeasibility'];text+='\n## '+p['profile']+'\n\n'
 text+=table(['S','Phase/type','Plancher vélo/course','Enveloppe actuelle vélo/course','Plafond natif avant/après','Plafond effectif entraînement','Minima indépendants de source','Événements déclarés','Nécessaires satisfaits'],[[w['week'],str(w['phase'])+'/'+w['type'],str(w['nativeFloors'].get('slLongRideMin'))+'/'+str(w['nativeFloors'].get('slLongRunMin')),('180/75'if'aerobic'in p['profile']else'150/90'),str(old['weeks'][n]['nativeCeiling'])+'/'+str(w['nativeCeiling']),w['effectiveCeiling'],w['necessaryLowerBound'],len(w['competitionReservations']),w['passesNecessaryChecks']]for n,w in enumerate(f['weeks'])])
 first=next(x for x in f['failures']if x['classification']=='current_individual_envelope_conflicts_with_programming_floor')
 text+=f'\n\nPremier témoin de capacité : S{first["week"]}, plancher{first["floor"]} min contre enveloppe documentée{first["documentedCap"]} min. Le refus demeure après la correction du budget. Le tableau des sources compatibles ne constitue pas un calendrier joint ; les minima indépendants ne garantissent ni placement ni progression sportive.\n'
text+='\n## Correction logicielle expérimentale du budget\n\nLes fixtures V10 avaient fixé weeklyHours à10 h mais conservé volumeRamp.weeklyHoursTarget à14 h depuis le cas QA initial. La copie V13 réconcilie la cible à10 h et maintient week1HoursMax8, pourcentages/paramètres existants, planchers, historique et enveloppes. Les plafonds natifs de charge ne dépassent plus600 min ; la récupérationS4 native devient420 au lieu de447, sans affecter le temps250 des blocs déjà examinés. La note QA de charge récente héritée reste explicitement synthétique : aucune mesure réelle ni conversion TSS→heures n’est inventée. Les fichiers V10–V12 ne sont pas modifiés.\n\nUne borne native supérieure au budget coach n’était pas un volume obligatoire. L’intersection avec600 min était déjà imposée dans le premier audit ; la réconciliation corrige maintenant aussi l’entrée de rampe. Cette amélioration ne fait pas disparaître les refus de longues.\n\n## Pourquoi ne pas produire le plan\n\nLe profil aérobie ne dispose pas d’une preuve couvrant90 min de course en S5 sous son enveloppe actuelle75 ; l’équilibré manque de preuve pour95 min en S6 sous son enveloppe90, puis les exigences montent à100. Le simple passage de semaines planifiées ne crée pas cette capacité. Ces bornes synthétiques actuelles ne sont pas des plafonds physiologiques universels et ne prouvent pas l’impossibilité future d’un Ironman. Une nouvelle réponse documentée ou une revue méthodologique serait nécessaire ; aucune n’est inventée pour assembler.\n\nS’ajoutent des temps individuels de nage inconnus, des recettes insuffisamment chronométrées, un brick corrigé seulement pour sa portion active, la réponse posturale non observée et la préparation spécifique/nutrition/force non attestées. La sélection de sources examine un pool borné et les domaines actuellement étayés ; une absence dans ce pool n’est pas une preuve d’absence globale dans les920 fiches.\n\nLes minima d’entraînement sont dérivés des helpers existants et séparés des réservations officielles de compétition. La compétition déclarée n’est pas fabriquée comme séance catalogue ou entraînement ; sa durée demeure inconnue et n’est pas imputée au plafond600 min d’entraînement. Les phases et types natifs, y compris taper en phasebuild, sont exposés sans les modifier pour faciliter une insertion.\n\nConclusion opérationnelle : plan=null pour chaque profil. Aucune construction de16 semaines sportivement défendable n’est engagée au-delà des préconditions échouées. La validation technique/sportive/globale d’un plan complet n’est pas comptée passée : elle est non applicable faute d’objet admissible. Le contrôle de tout l’horizon est un audit nécessaire, pas une collection de microcycles validés ni un générateur complet démontré.'
put('FULL_IRONMAN_FEASIBILITY.md',text)
text='# Diagnostics sportifs et couverture réelle\n\n| Niveau | Exécution / résultat | Limite |\n|---|---|---|\n| Sources | Offres des16 contextes, phases, restrictions, bornes et témoins examinés | Grammaire temporelle partielle ; inconnues non changées en zéros |\n| Nage45 | Vérification du contrat numérique et des données individuelles | Temps complet non confirmé pour les deux profils |\n| Overlay brick | Contrat actif55 corrigé en parallèle, erreur originale conservée | Temps total et utilisation restent non exécutables |\n| Blocs V12 | Maintien et progression rejoués, plans et diagnostics identiques | Pas de supériorité ni d’adaptation réellement démontrée |\n| Préparation16 | Toutes les exigences de l’horizon et capacités actuelles examinées avant/après correction de budget | Aucun plan complet admissible émis |\n| Validateurs de plan complet16 | Non applicables :plan=null | Ne sont jamais comptés réussis |\n| Sécurité/pertinence générale | Non attestées | Revue indépendante et réponses nécessaires |\n\n## Classes de problèmes\n\n- **Défaut de catalogue prouvé** :55 min de composantes obligatoires dépassent le maximum45 de la fiche de transition.\n- **Bornes ou description insuffisantes** : durées annoncées sous un minimum de recette ; temps non attribué ; parseur incomplet. Ces cas sont séparés d’un conflit certain et d’une séance entièrement impossible.\n- **Défaut logiciel expérimental corrigé** : cible de rampe14 h héritée malgré budget10 h. Aucune règle de production n’est changée.\n- **Contradiction programmation/preuve actuelle** : planchers futurs de longue course au-dessus des enveloppes actuellement documentées ; aucune adaptation inventée. Ce n’est pas un diagnostic universel de danger.\n- **Inconnues individuelles** : autres nages, tests/provenance, capacité posturale et récupération, transitions, force et nutrition réellement tolérées.\n- **Erreurs réelles de prescription empêchées** : il serait erroné de tronquer les blocs/repos, compter55 min comme55 min de vélo, relever une capacité sans preuve, supprimer une discipline ou afficher un plan incomplet comme complet. Ces opérations ne sont pas effectuées.\n- **Contrôles non applicables** : validation d’un calendrier16 semaines qui n’a pas été construit ; besoins spécialisés dont les prérequis individuels ne sont pas établis.\n\nLes diagnostics historiques des blocs restent bruts et inchangés ; les témoins de portée V12 n’en suppriment aucune sévérité. L’audit V13 n’utilise pas le passage des tests comme attestation sportive. Le maintien et la progression restent des hypothèses à revoir, pas des recommandations opérationnelles départagées.\n\nLes600 références et les preuves V2–V12 ne sont pas régénérées ou modifiées. La non-régression multiobjectifs porte sur le logiciel existant ; aucune nouvelle préparation d’une autre famille n’est attestée.'
put('SPORTING_DIAGNOSTICS.md',text)
# Counts are parsed from completed logs, not inferred from successful plan assembly.
validation={'version':'det-v13-1','types':'passed','governancePassed':62,'completePlansProduced':0,'full16PlanValidation':'not_applicable_no_admissible_plan','independentReplay':rep}
for name,path in [('experimental',R/'evidence/final-delta/experimental.txt'),('historical',R/'evidence/validation/historical.txt'),('targeted',E/'tests.txt')]:
 log=path.read_text();m=re.search(r'Tests\s+(\d+) passed(?:\s*\|\s*(\d+) skipped)?(?:\s*\|\s*(\d+) todo)?',log);assert m,name
 validation[name]={'passed':int(m[1]),'skipped':int(m[2]or 0),'todo':int(m[3]or 0),'proof':str(path.relative_to(R))}
validation['targetedOverlapsExperimental']=True
(R/'validation-summary.json').write_text(json.dumps(validation,indent=2))
dashboard={'version':'det-v13-1','recommendation':'NO-GO','profiles':2,'horizonWeeksEach':16,'configurationsBeforeAfter':2,'distinctProfileWeeks':32,'completePlansProduced':0,'expertReviewed':0,'catalogueSources':len(audit),'catalogueCoverage':data['catalogue']['counts'],'rampTargetReconciledFrom14to10Hours':True,'profilesResults':[{'id':p['profile'],'status':p['result']['status'],'firstCapacityConflict':next(x for x in p['result']['failures']if x['classification']=='current_individual_envelope_conflicts_with_programming_floor'),'swim45Confirmed':False,'plan':None}for p in data['profiles']]}
(R/'dashboard.json').write_text(json.dumps(dashboard,indent=2))
text='# Résultats V13 — DRAFT / NO-GO\n\n**Aucun plan Ironman complet admissible de16 semaines n’est produit.** Les préconditions échouent avec les preuves actuelles ; le refus est conservé plutôt que d’augmenter artificiellement les capacités, tronquer une recette ou remplir le calendrier.\n\n'
text+=table(['Profil','Première contradiction de longue course','Nage45 min confirmée','Préparation complète'],[[p['profile'],f'S{next(x for x in p["result"]["failures"]if x["classification"]=="current_individual_envelope_conflicts_with_programming_floor")["week"]}','non','refusée avec témoins']for p in data['profiles']])
text+='\n\n## Améliorations vérifiées\n\n1. Audit de340 sources proposées sur l’horizon, avec couverture et inconnues distinctes. Le parseur partiel ne confond plus Main et séance entière dans cette couche. L’essai initial supersédé est conservé.\n2. Overlay expérimental de la transition :30 min vélo +25 course actives ; temps total inconnu. Source de production, phases et intensités préservées ; aucune séance55 min artificiellement déclarée complète.\n3. Nage : CSS90 de crawl seulement pour l’aérobie, CSS absente pour l’équilibré. Les autres temps manquent ; contrat numérique45 min accepté ne vaut pas faisabilité individuelle.\n4. Copie de configuration V13 réconciliant la cible de rampe14→10 h, tout en conservant plafonds initiaux, planchers et enveloppes. Les refus de longues restent présents après correction :90>75 en S5 pour l’aérobie,95>90 en S6 pour l’équilibré.\n5. Maintien et progression V12 recontrôlés avec plans/diagnostics identiques, sans supériorité démontrée ni adaptation acquise. Les principes Lorang restent des principes d’individualisation et réévaluation, pas des quotas universels.\n\n'
text+=f'Typage réussi ;62 tests de gouvernance ;{validation["experimental"]["passed"]} tests expérimentaux réussis ({validation["experimental"]["skipped"]} opt-in ignorés) ;{validation["historical"]["passed"]} historiques réussis ({validation["historical"]["skipped"]} ignoré,{validation["historical"]["todo"]} todo). Les{validation["targeted"]["passed"]} tests ciblés de preuve recouvrent la suite expérimentale et un test opt-in, sans addition comme couverture indépendante. Deux processus reproduisent exactement trois artefacts.\n\n'
text+='La correction tardive du seul paramètre expérimental de rampe a été suivie d’un nouveau typage et de toute la suite expérimentale ; les résultats historiques déjà réussis concernent des sources et entrées inchangées. Une tentative de validation différentielle a échoué sur le typage de la copie de profil ; ses preuves sont conservées dans evidence/rejected-delta-attempt-2. La correction générique a été revalidée sans changement de règle sportive. La première preuve opt-in a aussi dépassé le délai Vitest de5 s pendant son archivage (5,804 s) ; elle est conservée et non acceptée. Le rejeu de preuve utilise30 s par test sous plafond de processus180 s, sans modifier les assertions ou règles sportives. Aucune régression sportive critique introduite n’est détectée par ces contrôles. Les validateurs de préparation complète16 semaines ne sont pas exécutés sur un faux plan : ils restent non applicables.\n\n## Décisions et preuves nécessaires avant nouvelle construction\n\n- Exécutions complètes de nage avec allures/provenance des différentes nages et repos ; ne pas déduire ces valeurs d’un CSS de crawl ou du niveau.\n- Réévaluation documentée de la capacité des longues et de la récupération avant les futurs planchers ; aucune progression acquise par simple calendrier. Toute modification de plancher/méthodologie nécessiterait une revue distincte, jamais un assouplissement pour assembler.\n- Temps complet des transitions et recettes réellement exécutables, prérequis de force et nutrition individualisée ; le contrat actif corrigé du brick ne suffit pas.\n- Revue sportive indépendante des hypothèses de maintien/consolidation posturale et des phases spécifiques/affûtage avant promotion.\n\nLes références V2–V12 et les600 configurations restent intactes. Aucun accès Nolio, donnée réelle écrite, moteur/validateur de production modifié, migration, fusion, déploiement, publication Lovable, appel payant ou promotion automatique. Les dix unités sont bornées par une échéance absolue de60 minutes ; aucun processus permanent de développement n’est revendiqué.\n\n[Inventaire des dossiers](README.md), [matrice16 semaines](FULL_IRONMAN_FEASIBILITY.md), [registre](REPRISE.md).'
put('V13_RESULTS.md',text)
print(json.dumps({'sources':len(audit),'completePlans':0,'profileWeeks':32,'tests':validation['experimental']['passed'],'replayIdentical':True}))
